import groovy.json.JsonSlurper
import java.io.File
import java.security.MessageDigest

plugins { id("com.android.library") }

// Independent Android 9 guest userland. The prepared tree is generated by
// scripts/prepare-a9.py in this module; -PguestRuntimeA9Prepared=<dir> overrides it.
// Everything the guest needs at runtime (rootfs, prepared assets, jniLibs) is
// produced here, and .gitignore keeps the multi-GB images out of the repository.
val preparedRoot: File? = providers.gradleProperty("guestRuntimeA9Prepared").orNull
    ?.let { file(it) }
val bundledRoot = projectDir.resolve("prepared")
val runtimeRoot = preparedRoot ?: bundledRoot

android {
    namespace = "io.a10vm.guestruntime.a9"
    compileSdk = 35
    defaultConfig { minSdk = 28 }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    sourceSets.getByName("main") {
        jniLibs.srcDir(runtimeRoot.resolve("jniLibs"))
        assets.srcDir(runtimeRoot.resolve("assets"))
    }
}

fun sha256(file: File): String {
    val digest = MessageDigest.getInstance("SHA-256")
    file.inputStream().use { input ->
        val buffer = ByteArray(1 shl 16)
        while (true) {
            val count = input.read(buffer)
            if (count < 0) break
            digest.update(buffer, 0, count)
        }
    }
    return digest.digest().joinToString("") { "%02x".format(it) }
}

val verifyRuntimeA9 = tasks.register("verifyRuntimeA9") {
    doLast {
        if (providers.gradleProperty("ciSkipNativeVerify").isPresent) return@doLast
        val manifest = runtimeRoot.resolve("assets/guest-runtime-a9-inputs.json")
        check(manifest.isFile) {
            "missing Android 9 runtime inputs: $manifest\n" +
                "run: python guest-runtime-a9/scripts/prepare-a9.py\n" +
                "or:  ./gradlew :guest-runtime-a9:prepareA9Runtime\n" +
                "or:  -PguestRuntimeA9Prepared=<prepared dir>"
        }
        val json = JsonSlurper().parse(manifest) as Map<*, *>
        check((json["guestSdk"] as Number).toInt() == 28) { "guestSdk must be 28" }
        check((json["frameworkSdk"] as Number).toInt() == 28) { "frameworkSdk must be 28" }
        val roles = json["platformLibraries"] as? Map<*, *>
        check(roles != null) { "platformLibraries is required" }
        for (role in listOf("propertyClient", "guestDevices", "binderDevices",
                           "guestLog", "managerPolicy", "binderCore", "halModules")) {
            check(roles!![role] is String) { "platformLibraries.$role is required" }
        }
        val files = json["files"] as List<*>
        check(files.isNotEmpty()) { "No native files in the A9 manifest" }
        var checked = 0
        for (item in files) {
            val entry = item as Map<*, *>
            val logical = entry["logical"] as String
            val source = entry["source"] as String
            check(source in setOf("redroid9", "aosp9", "project-a9")) {
                "Unexpected source '$source' for $logical"
            }
            check(!logical.startsWith("liba10vm-") && !logical.startsWith("liba10")) {
                "Android 10 logical name in A9 prepared: $logical"
            }
            check(logical !in setOf("liba9vm-malloc-leak-shim.so", "liba9vm-libdl-compat.so")) {
                "ABI shim in A9 prepared: $logical"
            }
            val file = runtimeRoot.resolve("jniLibs/arm64-v8a/" + entry["name"])
            check(file.isFile) { "Missing A9 native input: $file" }
            check(file.length() == (entry["bytes"] as Number).toLong()) {
                "Size mismatch for $logical"
            }
            check(sha256(file) == entry["sha256"]) { "SHA-256 mismatch for $logical" }
            checked += 1
        }
        logger.lifecycle("A9 runtime verified: $checked native files")
    }
}
tasks.named("preBuild").configure { dependsOn(verifyRuntimeA9) }

// Explicit regeneration of the prepared tree. It is not wired into preBuild
// because it rewrites ~1 GB of assets and needs Python + JDK + d8.
val prepareA9Runtime = tasks.register<Exec>("prepareA9Runtime") {
    group = "android9"
    description = "Regenerate guest-runtime-a9/prepared from the Redroid 9 rootfs"
    workingDir = projectDir
    commandLine("python", projectDir.resolve("scripts/prepare-a9.py").absolutePath)
}

tasks.withType<org.gradle.api.tasks.bundling.Zip>().configureEach { isZip64 = true }
